"use strict";
const APP={name:"REMESAS",version:"4.3.2",lang:localStorage.getItem("remesas_lang_v4")||"es",session:null,config:null,access:null,moneyKey:"remesas_money_v4",expensesKey:"remesas_expenses_v4",familyKey:"remesas_family_v4",prefsKey:"remesas_prefs_v4",savingsKey:"remesas_savings_v4",plansKey:"remesas_plans_v4"},app=document.getElementById("app");
const esc=v=>String(v??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#039;"),t=(es,en)=>APP.lang==="en"?en:es,money=v=>new Intl.NumberFormat(APP.lang==="en"?"en-US":"es-US",{style:"currency",currency:"USD",maximumFractionDigits:2}).format(Number(v)||0),num=v=>Number(v)||0;
function getJSON(k,f){try{return JSON.parse(localStorage.getItem(k)||"")??f}catch{return f}}
function setJSON(k,v){localStorage.setItem(k,JSON.stringify(v))}
function token(){return APP.access||localStorage.getItem("remesas_access_v4")||""}
function headers(extra={}){const h={"Content-Type":"application/json",...extra},x=token();if(x)h["X-Remesas-Access-Token"]=x;h["X-Remesas-Language"]=APP.lang;return h}
async function api(url,options={}){const r=await fetch(url,{...options,headers:headers(options.headers||{})});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.detail||d.error||d.message||t("No se pudo completar esta acción.","This action could not be completed."));return d}
async function loadConfig(){try{APP.config=await api("/api/config?language="+encodeURIComponent(APP.lang))}catch{APP.config=APP.config||{app:{brand:"May Roga LLC"},countries:[],delivery_methods:[],payment_methods:[],help_topics:[]}}return APP.config}
async function serviceStatus(){try{return await api("/api/access/status")}catch{return{active:false,remaining_seconds:0}}}
async function verifyAccess(){const s=await serviceStatus();if(s.active){APP.access=token();return true}return false}
async function startService(){try{const d=await api("/api/service/start",{method:"POST",body:"{}"});APP.session=d.session;return true}catch(e){showError(e.message);return false}}
function topbar(title="REMESAS"){return`<header class="topbar"><button class="btn secondary small" onclick="renderHome()">⌂</button><strong class="brand">${esc(title)}</strong><div class="top-actions"><button class="btn lang-btn small" onclick="changeLanguage()">${APP.lang==="es"?"EN":"ES"}</button></div></header>`}
function renderShell(content,title="REMESAS"){app.innerHTML=`<div class="app-shell">${topbar(title)}<main>${content}</main></div>`;scrollTo(0,0)}
function card(title,text,action,icon=""){return`<button class="action-card" onclick="${action}"><span class="action-icon">${icon}</span><strong>${esc(title)}</strong><small>${esc(text)}</small></button>`}
function getExpenses(){const x=getJSON(APP.expensesKey,[]);return Array.isArray(x)?x:[]}
function getSavings(){const x=getJSON(APP.savingsKey,[]);return Array.isArray(x)?x:[]}
function getFamily(){const x=getJSON(APP.familyKey,[]);return Array.isArray(x)?x:[]}
function getPlans(){const x=getJSON(APP.plansKey,[]);return Array.isArray(x)?x:[]}
function getPurchase(){const x=getJSON("remesas_purchase_v4",[]);return Array.isArray(x)?x:[]}
function freqFactor(f){return f==="weekly"?52/12:f==="biweekly"?26/12:1}
function freqText(f){return f==="weekly"?t("Cada semana","Every week"):f==="biweekly"?t("Cada quincena","Every two weeks"):f==="monthly"?t("Cada mes","Every month"):t("Una sola vez","One time")}
function countryName(id){const c=(APP.config?.countries||[]).find(x=>String(x.id||x.code||"").toUpperCase()===String(id||"").toUpperCase());if(!c)return id||"";return c.name?.[APP.lang]||c.name?.es||c.name?.en||c.id||id}
function getMoneyState(){return getJSON(APP.moneyKey,{have:0,income:0,incomeFreq:"monthly",incomeSource:"",monthlyIncome:0,incomeTotal:0,expenseTotal:0,savingsTotal:0,remittance:0,available:0,updatedAt:null})}
function recalcMoney(m){const e=getExpenses(),s=getSavings(),r=num(m.remittance||0);m.expenseTotal=e.reduce((a,x)=>a+num(x.monthlyAmount??x.amount),0);m.savingsTotal=s.reduce((a,x)=>a+num(x.amount),0);m.available=num(m.have||0)+num(m.incomeTotal||m.monthlyIncome||0)-num(m.expenseTotal)-num(m.savingsTotal)-r;m.updatedAt=new Date().toISOString();return m}
function saveMoney(){const m=getMoneyState();recalcMoney(m);setJSON(APP.moneyKey,m);return m}
function homeStats(){const m=saveMoney(),e=getExpenses(),f=getFamily(),s=getSavings(),p=getPlans();return`<div class="balance-grid"><div class="balance"><small>${esc(t("Disponible","Available"))}</small><b>${money(m.available)}</b><span>${esc(t("Lo que queda después de lo que registraste.","What remains after what you recorded."))}</span></div><div class="balance"><small>${esc(t("Gastos","Expenses"))}</small><b>${e.length}</b><span>${esc(t("Pagos que has anotado.","Payments you recorded."))}</span></div><div class="balance"><small>${esc(t("Familia","Family"))}</small><b>${f.length}</b><span>${esc(t("Personas que quieres recordar.","People you want to remember."))}</span></div><div class="balance"><small>${esc(t("Ahorros","Savings"))}</small><b>${s.length}</b><span>${esc(t("Dinero que decidiste guardar.","Money you chose to set aside."))}</span></div><div class="balance"><small>${esc(t("Planes","Plans"))}</small><b>${p.length}</b><span>${esc(t("Cosas que quieres lograr.","Things you want to achieve."))}</span></div></div>`}
function renderHome(){const brand=APP.config?.app?.brand||"May Roga LLC";app.innerHTML=`<div class="app-shell"><header class="hero"><div class="topbar"><strong class="brand">REMESAS<br><small>${esc(brand)}</small></strong><div class="top-actions"><button class="btn lang-btn small" onclick="changeLanguage()">${APP.lang==="es"?"EN":"ES"}</button></div></div><h1>${esc(t("TU DINERO, MÁS CLARO","YOUR MONEY, CLEARER"))}</h1><p>${esc(t("Entiende tu dinero con palabras sencillas. Mira qué tienes, qué entra, qué sale y qué puedes hacer.","Understand your money in simple words. See what you have, what comes in, what goes out, and what you can do."))}</p><div class="hero-actions"><button class="btn" onclick="renderRemittance()">💸 ${esc(t("QUIERO ENVIAR DINERO","I WANT TO SEND MONEY"))}</button><button class="btn secondary" onclick="renderHelp()">❓ ${esc(t("NO SÉ QUÉ HACER","I DON'T KNOW WHAT TO DO"))}</button></div></header><main><section class="section"><div class="section-title"><div><h2>${esc(t("Tu dinero, paso a paso","Your money, step by step"))}</h2><p>${esc(t("Cada número tiene una explicación. Nada aparece solo.","Every number has an explanation. Nothing appears alone."))}</p></div></div><div class="grid three">${card("TENGO","Lo que tienes ahora.","renderTengo()","💵")}${card("GANO","Lo que entra y de dónde viene.","renderGano()","➕")}${card("GASTO","Lo que sale y en qué se va.","renderExpenses()","➖")}${card("AHORRO","Lo que decides guardar.","renderSavings()","🏦")}${card("QUIERO","Lo que quieres comprar, lograr o ayudar.","renderGoals()","🛒")}${card("PUEDO","Lo que queda después de tus decisiones.","renderPuedo()","📅")}${card("HAGO","La siguiente acción clara.","renderHago()","✅")}</div>${homeStats()}</section><section class="section"><div class="grid two">${card("GUÍA RÁPIDA","Te lleva paso a paso para preparar una remesa.","renderQuickGuide()","🧭")}${card("APRENDER","Aprende sin palabras complicadas.","renderLearn()","📖")}${card("COMPARAR","Mira las cuatro remesadoras en un solo lugar.","renderRemittance()","🔎")}${card("PDF DE MI DINERO","Guarda una copia de lo que organizaste.","exportMoneyPDF()","📄")}${card("ENTRAR PDF","Trae un PDF de REMESAS y recupera tus datos.","pickPDF()","📥")}${card("AYUDA","Pregunta y recibe una respuesta corta.","renderHelp()","❓")}</div></section><section class="section"><div class="card"><h2>${esc(t("¿Qué quieres resolver hoy?","What do you want to solve today?"))}</h2><p>${esc(t("Escríbelo como se lo dirías a una persona.","Write it the way you would tell a person."))}</p><textarea id="freeNeed" maxlength="2000" placeholder="${esc(t("Ejemplo: quiero mandar $200 a México y quiero saber si me alcanza.","Example: I want to send $200 to Mexico and know if I can afford it."))}"></textarea><button class="btn" onclick="understandNeed()">${esc(t("AYÚDAME CON ESTO","HELP ME WITH THIS"))}</button></div></section><section class="section"><div class="legal"><b>${esc(t("Para tu tranquilidad","For your peace of mind"))}</b><p>${esc(t("REMESAS te ayuda a entender y organizar tus propios datos. No recibe ni envía tu dinero. Antes de enviar, revisa la cantidad, el destinatario y las condiciones que muestre la remesadora oficial.","REMESAS helps you understand and organize your own information. It does not receive or send your money. Before sending, review the amount, recipient, and conditions shown by the official provider."))}</p></div><button class="btn danger" onclick="deleteLocalData()">${esc(t("BORRAR MIS DATOS","DELETE MY DATA"))}</button></section><footer class="footer">${esc(brand)} · REMESAS ${esc(APP.version)}<div class="footer-links"><button onclick="renderHelp()">${esc(t("Ayuda","Help"))}</button><button onclick="renderAbout()">${esc(t("Privacidad","Privacy"))}</button></div></footer></main></div>`}
function renderTengo(){const m=getMoneyState();renderShell(`<section class="section"><div class="card"><h1>💵 ${esc(t("TENGO","I HAVE"))}</h1><p>${esc(t("Primero sabemos con cuánto cuentas. Así no hacemos planes con dinero que no tienes.","First we find out what you have. That way we do not plan with money you do not have."))}</p><label>${esc(t("¿Cuánto dinero tienes disponible ahora?","How much money do you have available now?"))}</label><input id="haveAmount" type="number" min="0" step=".01" value="${esc(m.have||"")}"><button class="btn" onclick="saveTengo()">${esc(t("GUARDAR Y VER QUÉ SIGNIFICA","SAVE AND SEE WHAT IT MEANS"))}</button><div id="tengoResult"></div></div></section>`,t("TENGO","I HAVE"));showTengo(m.have)}
function saveTengo(){const v=num(document.getElementById("haveAmount")?.value);if(v<0)return showError(t("Escribe una cantidad válida.","Enter a valid amount."));const m=getMoneyState();m.have=v;recalcMoney(m);setJSON(APP.moneyKey,m);showTengo(v)}
function showTengo(v){const b=document.getElementById("tengoResult");if(!b)return;b.innerHTML=`<div class="notice"><h3>${money(v)}</h3><p>${esc(t("Ese número es el dinero que dices que tienes disponible ahora. Lo usamos como punto de partida. Cuando registres gastos, ahorro o una remesa, el dinero disponible cambiará porque ese dinero ya tendrá un destino.","That number is the money you say you have available now. We use it as the starting point. When you record expenses, savings, or a remittance, available money changes because that money now has a purpose."))}</p></div><button class="btn secondary" onclick="renderPuedo()">${esc(t("¿QUÉ PUEDO HACER CON ESTO?","WHAT CAN I DO WITH THIS?"))}</button>`}
function renderGano(){const m=getMoneyState();renderShell(`<section class="section"><div class="card"><h1>➕ ${esc(t("GANO","I EARN"))}</h1><p>${esc(t("Aquí anotamos el dinero que entra. Saber cuánto entra ayuda a saber cuánto puedes gastar, guardar o enviar.","Here we record money coming in. Knowing what comes in helps you know what you can spend, save, or send."))}</p><label>${esc(t("¿Cuánto recibes?","How much do you receive?"))}</label><input id="gainAmount" type="number" min="0" step=".01" value="${esc(m.income||"")}"><label>${esc(t("¿Cada cuánto?","How often?"))}</label><select id="gainFreq"><option value="weekly">${esc(t("Cada semana","Every week"))}</option><option value="biweekly">${esc(t("Cada quincena","Every two weeks"))}</option><option value="monthly">${esc(t("Cada mes","Every month"))}</option></select><label>${esc(t("¿De dónde viene?","Where does it come from?"))}</label><input id="gainSource" maxlength="100" value="${esc(m.incomeSource||"")}" placeholder="${esc(t("Trabajo, negocio, ayuda...","Work, business, help..."))}"><button class="btn" onclick="saveGano()">${esc(t("GUARDAR Y EXPLICAR","SAVE AND EXPLAIN"))}</button><div id="ganoResult"></div></div></section>`,t("GANO","I EARN"));document.getElementById("gainFreq").value=m.incomeFreq||"monthly"}
function saveGano(){const v=num(document.getElementById("gainAmount")?.value),f=document.getElementById("gainFreq")?.value||"monthly",src=(document.getElementById("gainSource")?.value||"").trim();if(v<0)return showError(t("Escribe una cantidad válida.","Enter a valid amount."));const m=getMoneyState();m.income=v;m.incomeFreq=f;m.incomeSource=src;m.monthlyIncome=v*freqFactor(f);m.incomeTotal=m.monthlyIncome;recalcMoney(m);setJSON(APP.moneyKey,m);const b=document.getElementById("ganoResult");if(!b)return;b.innerHTML=`<div class="notice"><h3>${money(m.monthlyIncome)}</h3><p>${esc(t(`Este es el equivalente mensual de lo que recibes. Lo usamos para comparar tus entradas con tus gastos. Si cobras ${freqText(f).toLowerCase()}, lo pasamos a una misma medida para verlo con claridad.`,`This is the monthly equivalent of what you receive. We use it to compare your income with your expenses.`))}</p>${src?`<p>${esc(t(`Lo registraste como: ${src}.`,`You recorded it as: ${src}.`))}</p>`:""}</div><button class="btn secondary" onclick="renderPuedo()">${esc(t("VER QUÉ ME QUEDA","SEE WHAT I HAVE LEFT"))}</button>`}
function renderExpenses(){const e=getExpenses();renderShell(`<section class="section"><div class="card"><h1>➖ ${esc(t("GASTO","SPEND"))}</h1><p>${esc(t("Cada gasto que anotas explica por qué baja tu dinero disponible.","Every expense you record explains why your available money goes down."))}</p><label>${esc(t("¿En qué gastaste?","What did you spend on?"))}</label><input id="expenseName" maxlength="120" placeholder="${esc(t("Comida, casa, carro...","Food, home, car..."))}"><label>${esc(t("¿Cuánto?","How much?"))}</label><input id="expenseAmount" type="number" min=".01" step=".01"><label>${esc(t("¿Cada cuánto?","How often?"))}</label><select id="expenseFrequency"><option value="monthly">${esc(t("Cada mes","Every month"))}</option><option value="weekly">${esc(t("Cada semana","Every week"))}</option><option value="biweekly">${esc(t("Cada quincena","Every two weeks"))}</option><option value="one_time">${esc(t("Una sola vez","One time"))}</option></select><button class="btn" onclick="addExpense()">${esc(t("GUARDAR GASTO","SAVE EXPENSE"))}</button></div><div class="list">${e.length?e.map((x,i)=>`<div class="card"><b>${esc(x.description||"")}</b><strong>${money(x.amount)}</strong><p class="small">${esc(freqText(x.frequency))}${x.frequency!=="one_time"?` · ${money(x.monthlyAmount)}/${esc(t("mes","month"))}`:""}</p><button class="btn danger small" onclick="removeExpense(${i})">${esc(t("Borrar","Delete"))}</button></div>`).join(""):`<div class="empty">${esc(t("Todavía no has anotado gastos.","You have not recorded expenses yet."))}</div>`}</div><button class="btn secondary" onclick="renderPuedo()">${esc(t("VER QUÉ CAMBIÓ","SEE WHAT CHANGED"))}</button></section>`,t("GASTO","SPEND"))}
function addExpense(){const d=(document.getElementById("expenseName")?.value||"").trim(),a=num(document.getElementById("expenseAmount")?.value),f=document.getElementById("expenseFrequency")?.value||"monthly";if(!d||a<=0)return showError(t("Escribe qué fue y cuánto costó.","Enter what it was and how much it cost."));const monthlyAmount=f==="weekly"?a*52/12:f==="biweekly"?a*26/12:a,e=getExpenses();e.push({description:d,amount:a,frequency:f,monthlyAmount,createdAt:new Date().toISOString()});setJSON(APP.expensesKey,e);saveMoney();renderExpenses()}
function removeExpense(i){const e=getExpenses();if(i<0||i>=e.length)return;e.splice(i,1);setJSON(APP.expensesKey,e);saveMoney();renderExpenses()}
function renderSavings(){const s=getSavings();renderShell(`<section class="section"><div class="card"><h1>🏦 ${esc(t("AHORRO","SAVINGS"))}</h1><p>${esc(t("Ahorrar no significa perder ese dinero. Significa ponerlo aparte para algo que te importa.","Saving does not mean losing that money. It means setting it aside for something that matters to you."))}</p><label>${esc(t("¿Cuánto quieres guardar?","How much do you want to save?"))}</label><input id="saveAmount" type="number" min=".01" step=".01"><label>${esc(t("¿Para qué?","What for?"))}</label><input id="savePurpose" maxlength="100" placeholder="${esc(t("Casa, carro, viaje, emergencia...","Home, car, trip, emergency..."))}"><button class="btn" onclick="saveSavings()">${esc(t("GUARDAR Y VER QUÉ CAMBIA","SAVE AND SEE WHAT CHANGES"))}</button></div><div class="list">${s.length?s.map((x,i)=>`<div class="card"><b>${esc(x.purpose||t("Ahorro","Savings"))}</b><strong>${money(x.amount)}</strong><p>${esc(t("Este dinero está apartado para ese propósito.","This money is set aside for that purpose."))}</p><button class="btn danger small" onclick="removeSavings(${i})">${esc(t("Borrar","Delete"))}</button></div>`).join(""):`<div class="empty">${esc(t("Todavía no has separado dinero para una meta.","You have not set money aside for a goal yet."))}</div>`}</div></section>`,t("AHORRO","SAVINGS"))}
function saveSavings(){const a=num(document.getElementById("saveAmount")?.value),p=(document.getElementById("savePurpose")?.value||"").trim();if(a<=0||!p)return showError(t("Dime cuánto quieres guardar y para qué.","Tell me how much you want to save and what it is for."));const s=getSavings();s.push({amount:a,purpose:p,createdAt:new Date().toISOString()});setJSON(APP.savingsKey,s);saveMoney();renderSavings()}
function removeSavings(i){const s=getSavings();if(i<0||i>=s.length)return;s.splice(i,1);setJSON(APP.savingsKey,s);saveMoney();renderSavings()}
function renderFamily(){const f=getFamily();renderShell(`<section class="section"><div class="card"><h1>❤️ ${esc(t("FAMILIA","FAMILY"))}</h1><p>${esc(t("Guarda a quién quieres ayudar y cuánto piensas separar. Es una referencia para organizarte.","Keep a reference of who you want to help and how much you plan to set aside."))}</p><label>${esc(t("Nombre o apodo","Name or nickname"))}</label><input id="familyName" maxlength="80"><label>${esc(t("País","Country"))}</label><select id="familyCountry"><option value="">${esc(t("Elige un país","Choose a country"))}</option>${(APP.config?.countries||[]).map(c=>{const id=String(c.id||c.code||"").toUpperCase();return`<option value="${esc(id)}">${esc(c.name?.[APP.lang]||c.name?.es||id)}</option>`}).join("")}</select><label>${esc(t("¿Cuánto quieres ayudar?","How much do you want to help with?"))}</label><input id="familyAmount" type="number" min="0" step=".01"><button class="btn" onclick="saveFamily()">${esc(t("GUARDAR","SAVE"))}</button></div><div class="list">${f.length?f.map((x,i)=>`<div class="card"><b>${esc(x.name)}</b><p>${esc(countryName(x.country))}</p><strong>${money(x.amount)}</strong><p class="small">${esc(t("Cantidad que has pensado separar.","Amount you planned to set aside."))}</p><button class="btn danger small" onclick="removeFamily(${i})">${esc(t("Borrar","Delete"))}</button></div>`).join(""):`<div class="empty">${esc(t("Aquí aparecerá la familia que quieras recordar.","Family references you add will appear here."))}</div>`}</div></section>`,t("Familia","Family"))}
function saveFamily(){const name=(document.getElementById("familyName")?.value||"").trim(),country=document.getElementById("familyCountry")?.value||"",amount=num(document.getElementById("familyAmount")?.value);if(!name||!country||amount<0)return showError(t("Completa nombre, país y cantidad.","Complete name, country, and amount."));const f=getFamily();f.push({name,country,amount,createdAt:new Date().toISOString()});setJSON(APP.familyKey,f);renderFamily()}
function removeFamily(i){const f=getFamily();if(i<0||i>=f.length)return;f.splice(i,1);setJSON(APP.familyKey,f);renderFamily()}
function renderGoals(){const p=getPlans();renderShell(`<section class="section"><div class="card"><h1>🛒 ${esc(t("QUIERO","I WANT"))}</h1><p>${esc(t("Una meta no es un gasto de hoy. Es algo que quieres conseguir y para lo que puedes ir guardando dinero.","A goal is not today's expense. It is something you want to achieve and can save toward."))}</p><label>${esc(t("¿Qué quieres lograr?","What do you want to achieve?"))}</label><input id="planName" maxlength="120"><label>${esc(t("¿Cuánto necesitas?","How much do you need?"))}</label><input id="planTarget" type="number" min=".01" step=".01"><label>${esc(t("¿Ya tienes algo guardado para eso?","Do you already have something saved for it?"))}</label><input id="planSaved" type="number" min="0" step=".01"><button class="btn" onclick="savePlan()">${esc(t("GUARDAR META","SAVE GOAL"))}</button></div><div class="list">${p.length?p.map((x,i)=>{const left=Math.max(0,num(x.target)-num(x.saved));return`<div class="card"><h3>${esc(x.name)}</h3><p>${esc(t("Meta","Goal"))}: <b>${money(x.target)}</b></p><p>${esc(t("Guardado","Saved"))}: <b>${money(x.saved)}</b></p><p>${esc(t("Falta","Left"))}: <b>${money(left)}</b></p><p class="small">${esc(t("Ese número te dice cuánto falta para llegar a la cantidad que quieres.","That number tells you what remains to reach your target."))}</p><button class="btn danger small" onclick="removePlan(${i})">${esc(t("Borrar","Delete"))}</button></div>`}).join(""):`<div class="empty">${esc(t("Todavía no tienes una meta guardada.","You do not have a saved goal yet."))}</div>`}</div></section>`,t("QUIERO","I WANT"))}
function savePlan(){const name=(document.getElementById("planName")?.value||"").trim(),target=num(document.getElementById("planTarget")?.value),saved=num(document.getElementById("planSaved")?.value);if(!name||target<=0||saved<0)return showError(t("Dime qué quieres lograr y las cantidades.","Enter what you want to achieve and the amounts."));const p=getPlans();p.push({name,target,saved,createdAt:new Date().toISOString()});setJSON(APP.plansKey,p);renderGoals()}
function removePlan(i){const p=getPlans();if(i<0||i>=p.length)return;p.splice(i,1);setJSON(APP.plansKey,p);renderGoals()}
function renderPuedo(){const m=getMoneyState();recalcMoney(m);setJSON(APP.moneyKey,m);const positive=m.available>=0,msg=positive?t(`Según tus registros, aparecen ${money(m.available)} libres. Eso no significa que debas gastarlos. Significa que, con lo que registraste, todavía no tienen otro destino.`,`According to your records, ${money(m.available)} appears free. That does not mean you should spend it. It means that, from what you recorded, it has no other assigned purpose.`):t(`Tus registros muestran ${money(Math.abs(m.available))} más comprometidos que disponibles. Antes de agregar otra obligación, revisa gastos, ahorro y metas.`,`Your records show ${money(Math.abs(m.available))} more committed than available. Before adding another obligation, review expenses, savings, and goals.`);renderShell(`<section class="section"><div class="card"><h1>📅 PUEDO</h1><p>${esc(t("Juntamos tus números para explicar cuánto aparece libre según lo que registraste.","We combine your numbers to explain how much appears free from what you recorded."))}</p><div class="notice"><h2>${money(m.available)}</h2><p>${esc(msg)}</p></div><div class="result-list"><div><b>TENGO: ${money(m.have)}</b><small>${esc(t("Dinero que registraste ahora.","Money you recorded now."))}</small></div><div><b>GANO: ${money(m.monthlyIncome)}</b><small>${esc(t("Entrada mensual equivalente.","Monthly equivalent income."))}</small></div><div><b>GASTO: ${money(m.expenseTotal)}</b><small>${esc(t("Gastos mensuales según tus registros.","Monthly expenses according to your records."))}</small></div><div><b>AHORRO: ${money(m.savingsTotal)}</b><small>${esc(t("Dinero que decidiste apartar.","Money you decided to set aside."))}</small></div></div><button class="btn" onclick="renderHago()">${esc(t("¿QUÉ HAGO AHORA?","WHAT DO I DO NOW?"))}</button></div></section>`,"PUEDO")}
function renderHago(){const m=saveMoney(),msg=m.available<0?t("Primero revisa tus gastos y metas. Hay más dinero comprometido que disponible según tus registros.","First review your expenses and goals. More money is committed than available according to your records."):t(`Tienes ${money(m.available)} que aparece libre según tus registros. Ahora puedes revisar una compra, guardar dinero o preparar una remesa.`,`You have ${money(m.available)} that appears free according to your records. You can now review a purchase, save money, or prepare a remittance.`);renderShell(`<section class="section"><div class="card"><h1>✅ HAGO</h1><div class="notice"><h2>${money(m.available)}</h2><p>${esc(msg)}</p></div><div class="grid two">${card("ENVIAR","Preparar una remesa.","renderRemittance()","💸")}${card("AHORRAR","Apartar dinero.","renderSavings()","🏦")}${card("COMPRAR","Revisar una compra.","renderPurchase()","🛒")}${card("REVISAR","Volver a mis números.","renderMoney()","💰")}</div></div></section>`,"HAGO")}
function renderMoney(){const m=getMoneyState();recalcMoney(m);setJSON(APP.moneyKey,m);renderShell(`<section class="section"><div class="card"><h1>💰 ${esc(t("MI DINERO","MY MONEY"))}</h1><p>${esc(t("Aquí juntamos tus entradas y salidas para explicarte qué queda. No es una cuenta bancaria.","Here we combine your money coming in and going out to explain what remains. It is not a bank account."))}</p><div class="balance-grid"><div class="balance"><small>TENGO</small><b>${money(m.have)}</b><span>${esc(t("Lo que dices que tienes ahora.","What you say you have now."))}</span></div><div class="balance"><small>GANO</small><b>${money(m.monthlyIncome)}</b><span>${esc(t("Lo que entra en un mes equivalente.","What comes in during an equivalent month."))}</span></div><div class="balance"><small>GASTO</small><b>${money(m.expenseTotal)}</b><span>${esc(t("Lo que sale según tus registros.","What leaves according to your records."))}</span></div><div class="balance"><small>AHORRO</small><b>${money(m.savingsTotal)}</b><span>${esc(t("Lo que apartaste.","What you set aside."))}</span></div><div class="balance"><small>PUEDO</small><b>${money(m.available)}</b><span>${esc(t("Lo que queda después de lo registrado.","What remains after what you recorded."))}</span></div></div><div class="notice"><p>${esc(m.available>=0?t(`Te quedan ${money(m.available)} según tus registros. Este número sale de lo que pusiste en TENGO, GANO, GASTO y AHORRO.`,`You have ${money(m.available)} left according to your records. This number comes from what you entered in HAVE, EARN, SPEND, and SAVE.`):t(`Tus registros están ${money(Math.abs(m.available))} por encima del dinero que aparece disponible. Revisa qué gasto o meta puedes cambiar.`,`Your records are ${money(Math.abs(m.available))} above the money shown as available. Review which expense or goal you can change.`))}</p></div><button class="btn" onclick="renderPuedo()">${esc(t("EXPLICARME QUÉ PUEDO HACER","EXPLAIN WHAT I CAN DO"))}</button><button class="btn secondary" onclick="renderHago()">${esc(t("DIME EL SIGUIENTE PASO","TELL ME THE NEXT STEP"))}</button></div></section>`,t("Mi dinero","My money"))}
function renderWeek(){renderPeriod("weekly")}
function renderPeriod(period){const m=getMoneyState(),factor=period==="weekly"?4.333333:period==="biweekly"?2.166667:1,inc=num(m.monthlyIncome)/factor,exp=num(m.expenseTotal)/factor,sav=num(m.savingsTotal)/factor,a=inc-exp-sav,title=period==="weekly"?t("MI SEMANA","MY WEEK"):period==="biweekly"?t("MI QUINCENA","MY TWO WEEKS"):t("MI MES","MY MONTH");renderShell(`<section class="section"><div class="card"><h1>📆 ${esc(title)}</h1><p>${esc(t("Una vista corta para saber cómo vas sin llenar la pantalla de números.","A short view so you know how you are doing without filling the screen with numbers."))}</p><div class="notice"><h2>${money(a)}</h2><p>${esc(t(`Después de lo que registraste para este periodo, quedan aproximadamente ${money(a)}. Es una referencia hecha con tus propios datos.`,`After what you recorded for this period, approximately ${money(a)} remains. It is a reference based on your own data.`))}</p></div><div class="result-list"><div><b>${esc(t("Entra","Comes in"))}: ${money(inc)}</b><small>${esc(t("Dinero que esperas recibir en este periodo.","Money you expect to receive in this period."))}</small></div><div><b>${esc(t("Sale","Goes out"))}: ${money(exp)}</b><small>${esc(t("Gastos registrados para este periodo.","Expenses recorded for this period."))}</small></div><div><b>${esc(t("Guardas","Save"))}: ${money(sav)}</b><small>${esc(t("Dinero apartado para tus metas.","Money set aside for your goals."))}</small></div></div><button class="btn" onclick="renderHago()">${esc(t("¿QUÉ HAGO CON ESTO?","WHAT DO I DO WITH THIS?"))}</button></div></section>`,t("Mi periodo","My period"))}
function renderPurchase(){renderShell(`<section class="section"><div class="card"><h1>🛒 ${esc(t("PLANEAR UNA COMPRA","PLAN A PURCHASE"))}</h1><p>${esc(t("Antes de comprar, mira qué pasa con tu dinero después.","Before buying, see what happens to your money afterward."))}</p><label>${esc(t("¿Qué quieres comprar?","What do you want to buy?"))}</label><input id="purchaseName" maxlength="120"><label>${esc(t("¿Cuánto cuesta?","How much does it cost?"))}</label><input id="purchaseAmount" type="number" min=".01" step=".01"><button class="btn" onclick="checkPurchase()">${esc(t("VER QUÉ PASA","SEE WHAT HAPPENS"))}</button></div></section>`,t("Compra","Purchase"))}
function checkPurchase(){const n=(document.getElementById("purchaseName")?.value||"").trim(),a=num(document.getElementById("purchaseAmount")?.value),m=getMoneyState();if(!n||a<=0)return showError(t("Dime qué quieres comprar y cuánto cuesta.","Tell me what you want to buy and how much it costs."));const after=num(m.available)-a,explain=after>=0?t(`Después de esa compra te quedarían ${money(after)} según tus registros. Eso te permite ver la consecuencia antes de gastar.`,`After that purchase, you would have ${money(after)} left according to your records. This lets you see the consequence before spending.`):t(`Esa compra supera en ${money(Math.abs(after))} lo que aparece libre. Si la haces, tendrás que usar dinero que ya tiene otro destino o cambiar algo de tu plan.`,`That purchase exceeds the amount shown as free by ${money(Math.abs(after))}. If you make it, you would need to use money already assigned elsewhere or change your plan.`);renderShell(`<section class="section"><div class="card"><h1>${esc(n)}</h1><div class="notice"><h2>${money(after)}</h2><p>${esc(explain)}</p></div><button class="btn" onclick="renderPuedo()">${esc(t("REVISAR MIS NÚMEROS","REVIEW MY NUMBERS"))}</button><button class="btn secondary" onclick="renderHome()">${esc(t("VOLVER","BACK"))}</button></div></section>`,t("Resultado","Result"))}
async function renderRemittance(prefill=null){if(!await ensureService())return;const p=prefill||{},countries=APP.config?.countries||[];renderShell(`<section class="section"><div class="card"><h1>💸 ${esc(t("QUIERO ENVIAR DINERO","I WANT TO SEND MONEY"))}</h1><p>${esc(t("Dime solo lo necesario para preparar tu remesa. REMESAS no recibe ni envía el dinero.","Tell me only what is needed to prepare your remittance. REMESAS does not receive or send the money."))}</p><label>${esc(t("¿Cuánto quieres enviar?","How much do you want to send?"))}</label><input id="remAmount" type="number" min=".01" max="1000000" step=".01" value="${esc(p.amount||"")}"><label>${esc(t("¿A qué país?","To which country?"))}</label><select id="remCountry"><option value="">${esc(t("Selecciona","Select"))}</option>${countries.map(c=>{const id=c.id||c.code||"",name=c.name?.[APP.lang]||c.name?.es||c.name?.en||id;return`<option value="${esc(id)}" ${String(id).toUpperCase()===String(p.destination_country||"").toUpperCase()?"selected":""}>${esc(name)}</option>`}).join("")}</select><label>${esc(t("¿Qué te importa más?","What matters most?"))}</label><select id="remPriority"><option value="">${esc(t("Todavía no lo sé","I don't know yet"))}</option><option value="fastest">${esc(t("Que llegue rápido","Arrive quickly"))}</option><option value="save">${esc(t("Ahorrar","Save"))}</option><option value="recipient_gets_more">${esc(t("Que reciba más","Recipient gets more"))}</option><option value="urgent">${esc(t("Es urgente","It's urgent"))}</option><option value="balanced">${esc(t("Un poco de todo","A bit of everything"))}</option></select><button class="btn" onclick="compare()">${esc(t("VER MIS OPCIONES","SEE MY OPTIONS"))}</button></div></section>`,"REMESAS");if(p.priority)document.getElementById("remPriority").value=p.priority}
async function compare(){const a=num(document.getElementById("remAmount")?.value),d=document.getElementById("remCountry")?.value,p=document.getElementById("remPriority")?.value||null;if(a<=0||!d)return showError(t("Dime cuánto quieres enviar y a qué país.","Tell me how much you want to send and to which country."));if(!APP.session){if(!await startService())return}try{const r=await api(`/api/session/${encodeURIComponent(APP.session.session_id)}/compare`,{method:"POST",body:JSON.stringify({language:APP.lang,amount:a,currency:"USD",destination:d,priority:p})});APP.session.amount=a;APP.session.destination_country=d;showComparison(r)}catch(e){showError(e.message)}}
function providerCard(p){const id=p.provider_id||p.id||"",name=(p.name||id).toUpperCase(),url=p.official_url||p.url||"",status=p.commercial_status||p.commercial_data_status||"unavailable",verified=status==="verified";return`<div class="provider-card"><div class="provider-head"><h2>${esc(name)}</h2><span class="provider-status">${esc(verified?t("VERIFICADO","VERIFIED"):t("CONFIRMA CON LA REMESADORA","CONFIRM WITH PROVIDER"))}</span></div><p>${esc(verified?t("Hay información comercial verificada disponible.","Verified commercial information is available."):t("No mostramos tarifa, tasa o tiempo actual sin verificación. Confirma las condiciones directamente con la remesadora.","We do not show a current fee, rate, or delivery time without verification. Confirm current terms directly with the provider."))}</p><div class="provider-data">${p.methods?.length?`<p><b>${esc(t("Métodos","Methods"))}:</b> ${esc(Array.isArray(p.methods)?p.methods.join(", "):String(p.methods))}</p>`:""}${verified&&p.fee!=null?`<p><b>${esc(t("Tarifa","Fee"))}:</b> ${esc(p.fee)}</p>`:""}${verified&&p.exchange_rate!=null?`<p><b>${esc(t("Tasa","Rate"))}:</b> ${esc(p.exchange_rate)}</p>`:""}${verified&&p.recipient_amount!=null?`<p><b>${esc(t("Recibe","Recipient gets"))}:</b> ${esc(p.recipient_amount)}</p>`:""}${verified&&p.estimated_delivery?`<p><b>${esc(t("Entrega","Delivery"))}:</b> ${esc(p.estimated_delivery)}</p>`:""}</div>${url?`<button class="btn" onclick="openOfficial(${JSON.stringify(url)})">${esc(t("ABRIR SITIO OFICIAL","OPEN OFFICIAL SITE"))}</button>`:""}<button class="btn secondary" onclick="selectProvider('${esc(id)}')">${esc(t("ELEGIR PARA REVISAR","CHOOSE TO REVIEW"))}</button></div>`}
function showComparison(d){const all=[...(Array.isArray(d.results)?d.results:[]),...(Array.isArray(d.available_providers)?d.available_providers:[])],seen=new Set(),providers=all.filter(x=>{const id=x.provider_id||x.id;if(!id||seen.has(id))return false;seen.add(id);return true});renderShell(`<section class="section"><div class="card"><h1>🔎 COMPARAR</h1><p>${esc(d.explanation||t("Estas son las remesadoras que puedes revisar. Las condiciones finales deben confirmarse con la fuente oficial.","These are the providers you can review. Final terms must be confirmed with the official source."))}</p><div class="notice"><p>${esc(t("REMESAS no inventa tarifas, tasas, tiempos ni disponibilidad. Cuando un dato actual no está verificado, te lleva a la fuente oficial.","REMESAS does not invent fees, rates, delivery times, or availability. When a current fact is not verified, it sends you to the official source."))}</p></div>${providers.length?providers.map(providerCard).join(""):`<div class="empty">${esc(t("No hay opciones para mostrar.","There are no options to show."))}</div>`}<button class="btn secondary" onclick="renderLearn()">${esc(t("APRENDER ANTES DE ENVIAR","LEARN BEFORE SENDING"))}</button></div></section>`,"COMPARAR")}
async function selectProvider(id){if(!APP.session)return;try{const d=await api(`/api/session/${encodeURIComponent(APP.session.session_id)}/select/${encodeURIComponent(id)}`,{method:"POST",body:"{}"});if(d.session)APP.session=d.session;renderFinalCheck(id)}catch(e){showError(e.message)}}
function renderFinalCheck(id){const s=APP.session||{};renderShell(`<section class="section"><div class="card"><h1>✅ ${esc(t("REVISIÓN FINAL","FINAL REVIEW"))}</h1><p>${esc(t("Antes de continuar revisa cantidad, destinatario y forma de entrega.","Before continuing, review amount, recipient, and delivery."))}</p><div class="notice"><p><b>${esc(t("Cantidad","Amount"))}:</b> ${money(s.amount)}</p><p><b>${esc(t("País","Country"))}:</b> ${esc(countryName(s.destination_country))}</p></div><label class="check-row"><input id="ck1" type="checkbox">${esc(t("Revisé la cantidad.","I reviewed the amount."))}</label><label class="check-row"><input id="ck2" type="checkbox">${esc(t("Revisé al destinatario.","I reviewed the recipient."))}</label><label class="check-row"><input id="ck3" type="checkbox">${esc(t("Revisé cómo recibirá el dinero.","I reviewed how the money will be received."))}</label><button class="btn" onclick="finishCheck('${esc(id||"")}')">${esc(t("CONFIRMAR REVISIÓN","CONFIRM REVIEW"))}</button></div></section>`,"REVISIÓN")}
async function finishCheck(id){if(!["ck1","ck2","ck3"].every(x=>document.getElementById(x)?.checked))return showError(t("Revisa las tres casillas.","Review all three boxes."));if(!APP.session)return showError(t("La sesión de la remesa ya no está disponible.","The remittance session is no longer available."));try{const d=await api(`/api/session/${encodeURIComponent(APP.session.session_id)}/final-check`,{method:"POST",body:JSON.stringify({language:APP.lang,provider_id:id,amount:APP.session.amount,currency:"USD",destination:APP.session.destination_country,recipient_information_entered:true,checks:{amount:true,recipient:true,delivery:true}})});if(d.session)APP.session=d.session;const url=APP.session?.selected_option?.official_url||d.official_url||"";renderShell(`<section class="section"><div class="card"><h1>✅ ${esc(t("YA PUEDES CONTINUAR","YOU CAN CONTINUE"))}</h1><p>${esc(d.message||t("Revisa las condiciones finales en el sitio oficial antes de confirmar.","Review final terms on the official site before confirming."))}</p>${url?`<button class="btn" onclick="openOfficial(${JSON.stringify(url)})">${esc(t("IR AL SITIO OFICIAL","GO TO OFFICIAL SITE"))}</button>`:""}<button class="btn secondary" onclick="renderHome()">${esc(t("VOLVER","BACK"))}</button></div></section>`,"LISTO")}catch(e){showError(e.message)}}
function openOfficial(u){if(!u)return showError(t("No hay un sitio oficial disponible.","No official site is available."));try{const x=new URL(u,location.origin);if(!/^https?:$/.test(x.protocol))throw new Error();window.open(x.href,"_blank","noopener,noreferrer")}catch{showError(t("No pude abrir ese sitio.","I could not open that site."))}}
async function renderQuickGuide(){let d={};try{d=await api("/api/quick-guide")}catch{}const a=Array.isArray(d.steps)?d.steps:[],fallback=[{title:t("1. País","1. Country"),text:t("Confirma dónde recibirá el dinero.","Confirm where the money will be received.")},{title:t("2. Cantidad","2. Amount"),text:t("Confirma cuánto quieres enviar.","Confirm how much you want to send.")},{title:t("3. Entrega","3. Delivery"),text:t("Revisa cómo recibirá el dinero.","Review how the recipient will receive the money.")},{title:t("4. Pago","4. Payment"),text:t("Revisa cómo pagarás la remesa.","Review how you will pay.")},{title:t("5. Destinatario","5. Recipient"),text:t("Ten preparados los datos necesarios.","Have the required recipient information ready.")},{title:t("6. Revisión","6. Review"),text:t("Revisa todo antes de confirmar.","Review everything before confirming.")},{title:t("7. Sitio oficial","7. Official site"),text:t("Continúa directamente con la remesadora oficial.","Continue directly with the official provider.")}],steps=a.length?a:fallback;renderShell(`<section class="section"><div class="card"><h1>🧭 GUÍA RÁPIDA</h1><p>${esc(t("País → cantidad → entrega → pago → destinatario → revisión → sitio oficial.","Country → amount → delivery → payment → recipient → review → official site."))}</p><div class="result-list">${steps.map(x=>`<div><b>${esc(x.title||x.name||"Paso")}</b><small>${esc(x.text||x.description||"")}</small></div>`).join("")}</div><button class="btn" onclick="renderRemittance()">${esc(t("PREPARAR MI REMESA","PREPARE MY REMITTANCE"))}</button></div></section>`,"GUÍA RÁPIDA")}
async function renderLearn(){let d={};try{d=await api("/api/learn")}catch{}window.lessons=Array.isArray(d.lessons)?d.lessons:Array.isArray(d)?d:[];if(!window.lessons.length)window.lessons=[{title:t("Antes de empezar","Before you start"),text:t("Ten claro el país y la cantidad.","Know the country and amount.")},{title:t("El país","The destination"),text:t("Confirma dónde recibirá el dinero.","Confirm where the money will be received.")},{title:t("La cantidad","The amount"),text:t("Confirma cuánto quieres enviar.","Confirm how much you want to send.")},{title:t("La entrega","Delivery"),text:t("Revisa cómo puede recibirlo la persona.","Review how the recipient can receive it.")},{title:t("El pago","Payment"),text:t("Revisa cómo pagarás.","Review how you will pay.")},{title:t("El destinatario","Recipient"),text:t("Prepara la información necesaria.","Prepare the necessary information.")},{title:t("La revisión","Final review"),text:t("Revisa todo antes de continuar.","Review everything before continuing.")},{title:t("Sitio oficial","Official site"),text:t("Confirma las condiciones actuales con la remesadora.","Confirm current terms with the provider.") }];renderShell(`<section class="section"><div class="card"><h1>📖 APRENDER</h1><p>${esc(t("Aprende el proceso con palabras sencillas. La información actual debe confirmarse con la fuente oficial.","Learn the process in simple words. Current information must be confirmed with the official source."))}</p><div class="grid two">${window.lessons.map((x,i)=>card(x.title||`Paso ${i+1}`,x.summary||x.text||x.description||"",`showLesson(${i})`,"📘")).join("")}</div><button class="btn secondary" onclick="exportLearningPDF()">${esc(t("GUARDAR GUÍA","SAVE GUIDE"))}</button></div></section>`,"APRENDER")}
function showLesson(i){const x=(window.lessons||[])[i]||{};renderShell(`<section class="section"><div class="card"><h1>📘 ${esc(x.title||"")}</h1><p>${esc(x.text||x.description||x.summary||"")}</p><button class="btn" onclick="renderLearn()">${esc(t("VOLVER","BACK"))}</button><button class="btn secondary" onclick="renderRemittance()">${esc(t("PREPARAR REMESA","PREPARE REMITTANCE"))}</button></div></section>`,"APRENDER")}
async function renderHelp(){let d={};try{d=await api("/api/help")}catch{}window.helpTopics=Array.isArray(d.topics)?d.topics:Array.isArray(APP.config?.help_topics)?APP.config.help_topics:[];renderShell(`<section class="section"><div class="card"><h1>❓ AYUDA</h1><p>${esc(t("Dime qué necesitas y te ayudamos a encontrar el siguiente paso.","Tell me what you need and we will help find the next step."))}</p><textarea id="helpText" maxlength="1000" placeholder="${esc(t("Ejemplo: no sé cuánto puedo enviar.","Example: I don't know how much I can send."))}"></textarea><button class="btn" onclick="askHelp()">${esc(t("AYÚDAME","HELP ME"))}</button><div class="grid two">${window.helpTopics.map((x,i)=>card(x.title||x.name||x.id,x.description||x.text||"",`showHelpTopic(${i})`,"❓")).join("")}</div></div></section>`,"AYUDA")}
async function askHelp(){const q=(document.getElementById("helpText")?.value||"").trim();if(!q)return showError(t("Escribe tu pregunta.","Write your question."));try{const d=await api("/api/assistant",{method:"POST",body:JSON.stringify({language:APP.lang,text:q})});renderShell(`<section class="section"><div class="card"><h1>❓ ${esc(t("RESPUESTA","ANSWER"))}</h1><div class="assistant"><p>${esc(d.answer||d.message||t("Revisa la Guía Rápida.","Review the Quick Guide."))}</p></div><button class="btn" onclick="renderHelp()">${esc(t("VOLVER","BACK"))}</button></div></section>`,"AYUDA")}catch{showError(t("Revisa la Guía Rápida.","Review the Quick Guide."))}}
function showHelpTopic(i){const x=(window.helpTopics||[])[i]||{};renderShell(`<section class="section"><div class="card"><h1>❓ ${esc(x.title||x.name||x.id||"Ayuda")}</h1><p>${esc(x.description||x.text||"")}</p><button class="btn" onclick="renderHelp()">${esc(t("VOLVER","BACK"))}</button></div></section>`,"AYUDA")}
function renderAbout(){renderShell(`<section class="section"><div class="card"><h1>REMESAS</h1><p>${esc(t("Servicio independiente de May Roga LLC para entender, organizar y preparar información relacionada con dinero y remesas.","Independent May Roga LLC service to understand, organize, and prepare information related to money and remittances."))}</p><p>${esc(t("No es banco, institución financiera, procesador de pagos, remesadora, asesor financiero ni preparador de impuestos.","It is not a bank, financial institution, payment processor, remittance company, financial advisor, or tax preparer."))}</p><p>${esc(t("No recibe, guarda ni mueve el dinero del usuario. Las condiciones actuales de una remesa deben confirmarse directamente con la fuente oficial.","It does not receive, hold, or move the user's money. Current remittance terms must be confirmed directly with the official source."))}</p><button class="btn" onclick="renderHome()">${esc(t("VOLVER","BACK"))}</button></div></section>`,"PRIVACIDAD")}
async function ensureService(){if(await verifyAccess()){if(!APP.session){if(!await startService())return false}return true}renderGate();return false}
function renderGate(){app.innerHTML=`<div class="app-shell"><main><section class="hero"><div class="topbar"><strong class="brand">REMESAS<br><small>May Roga LLC</small></strong><button class="btn lang-btn small" onclick="changeLanguage()">${APP.lang==="es"?"EN":"ES"}</button></div><h1>${esc(t("TU DINERO, MÁS CLARO","YOUR MONEY, CLEARER"))}</h1><p>${esc(t("Organiza tu dinero, prepara remesas y revisa la información antes de continuar.","Organize your money, prepare remittances, and review information before continuing."))}</p><div class="card"><h2>${esc(t("ENTRA AL SERVICIO","ENTER THE SERVICE"))}</h2><p>${esc(t("Pago único de $10.99. Acceso durante 20 minutos.","One-time $10.99 payment. Access for 20 minutes."))}</p><button class="btn" onclick="startPaidAccess()">💳 ${esc(t("PAGAR $10.99 Y ENTRAR","PAY $10.99 AND ENTER"))}</button></div></section></main></div>`;installAdminGesture()}
async function startPaidAccess(){try{const d=await api("/api/create-checkout-session",{method:"POST",body:JSON.stringify({language:APP.lang})});if(d.url){location.href=d.url;return}if(d.checkout_url){location.href=d.checkout_url;return}showError(t("No se pudo abrir el pago.","Could not open payment."))}catch(e){showError(e.message)}}
function showServiceInfo(){renderShell(`<section class="section"><div class="card"><h1>REMESAS</h1><h2>${esc(t("$10.99 · 20 minutos","$10.99 · 20 minutes"))}</h2><p>${esc(t("Pago único. El acceso permite organizar tu información, preparar remesas, revisar opciones, aprender el proceso y llegar a la fuente oficial.","One-time payment. Access lets you organize your information, prepare remittances, review options, learn the process, and reach the official source."))}</p><button class="btn" onclick="startPaidAccess()">${esc(t("ENTRAR AL SERVICIO","ENTER SERVICE"))}</button></div></section>`,"SERVICIO")}
function installAdminGesture(){let n=0,last=0;const f=()=>{const now=Date.now();if(now-last>900)n=0;n++;last=now;if(n>=3){n=0;showAdmin()}};app.addEventListener("click",f)}
function showAdmin(){const x=document.createElement("div");x.className="modal-backdrop";x.innerHTML=`<div class="modal"><div class="modal-head"><h2>${esc(t("ENTRAR","SIGN IN"))}</h2><button class="close" onclick="this.closest('.modal-backdrop').remove()">×</button></div><label>${esc(t("USERNAME","USERNAME"))}</label><input id="adminUser" autocomplete="username"><label>${esc(t("PASSWORD","PASSWORD"))}</label><input id="adminPass" type="password" autocomplete="current-password"><button class="btn" onclick="adminLogin()">${esc(t("ENTRAR","SIGN IN"))}</button></div>`;document.body.appendChild(x);setTimeout(()=>document.getElementById("adminUser")?.focus(),50)}
async function adminLogin(){const u=document.getElementById("adminUser")?.value||"",p=document.getElementById("adminPass")?.value||"";if(!u||!p)return showError(t("Escribe usuario y clave.","Enter username and password."));try{const d=await api("/api/access/admin",{method:"POST",body:JSON.stringify({username:u,password:p})});APP.access=d.access_token||d.token||"";if(APP.access)localStorage.setItem("remesas_access_v4",APP.access);document.querySelector(".modal-backdrop")?.remove();if(await startService())renderHome()}catch{showError(t("Usuario o clave incorrectos.","Incorrect username or password."))}}
function moneyPDFData(){const m=getMoneyState();recalcMoney(m);return{kind:"REMESAS_MONEY",version:APP.version,created_at:new Date().toISOString(),money:m,expenses:getExpenses(),savings:getSavings(),family:getFamily(),plans:getPlans()}}
function printPDF(title,body){const data=moneyPDFData();let win;try{win=window.open("","_blank","noopener,noreferrer,width=900,height=800")}catch{}if(!win)return showError(t("Permite la ventana para guardar tu PDF.","Allow the window to save your PDF."));const encoded=btoa(unescape(encodeURIComponent(JSON.stringify(data)))),html=`<!DOCTYPE html><html lang="${APP.lang}"><head><meta charset="UTF-8"><title>${esc(title)}</title><style>body{font-family:Arial,Helvetica,sans-serif;margin:40px;color:#172033;line-height:1.5}h1{font-size:28px}h2{border-bottom:1px solid #ddd;padding-bottom:6px;margin-top:28px}.n{font-size:25px;font-weight:700;margin:8px 0}.muted{color:#777;font-size:8px;word-break:break-all}.box{border:1px solid #ddd;border-radius:10px;padding:16px;margin:14px 0}@media print{body{margin:20px}.no-print{display:none}}</style></head><body><div class="no-print"><button onclick="window.print()">${esc(t("GUARDAR COMO PDF","SAVE AS PDF"))}</button></div>${body}<p class="muted">REMESAS_DATA:${encoded}</p><script>window.onload=function(){setTimeout(function(){window.print()},400)};<\/script></body></html>`;win.document.open();win.document.write(html);win.document.close()}
function exportMoneyPDF(){const d=moneyPDFData(),m=d.money,body=`<h1>REMESAS — ${esc(t("MIS DATOS","MY DATA"))}</h1><p>${esc(new Date(d.created_at).toLocaleString(APP.lang==="es"?"es-US":"en-US"))}</p><div class="box"><h2>TENGO</h2><div class="n">${money(m.have)}</div><p>${esc(t("Dinero disponible que registraste como punto de partida.","Available money you recorded as your starting point."))}</p></div><div class="box"><h2>GANO</h2><div class="n">${money(m.monthlyIncome)}</div><p>${esc(t("Entrada mensual equivalente según la frecuencia que registraste.","Monthly equivalent based on the frequency you recorded."))}</p></div><div class="box"><h2>GASTO</h2><div class="n">${money(m.expenseTotal)}</div><p>${esc(t("Gastos mensuales que aparecen en tus registros.","Monthly expenses in your records."))}</p></div><div class="box"><h2>AHORRO</h2><div class="n">${money(m.savingsTotal)}</div><p>${esc(t("Dinero que registraste como apartado para tus metas.","Money you recorded as set aside for your goals."))}</p></div><div class="box"><h2>PUEDO</h2><div class="n">${money(m.available)}</div><p>${esc(t("Cantidad que queda según los datos que registraste después de las salidas anotadas.","Amount left according to the information you recorded after the listed outflows."))}</p></div><h2>GASTOS REGISTRADOS</h2>${d.expenses.map(x=>`<p>${esc(x.description||"")} — <b>${money(x.amount)}</b></p>`).join("")||`<p>${esc(t("Ninguno.","None."))}</p>`}<h2>AHORROS</h2>${d.savings.map(x=>`<p>${esc(x.purpose||"")} — <b>${money(x.amount)}</b></p>`).join("")||`<p>${esc(t("Ninguno.","None."))}</p>`}<h2>${esc(t("FAMILIA","FAMILY"))}</h2>${d.family.map(x=>`<p>${esc(x.name||"")} — ${esc(countryName(x.country))} — <b>${money(x.amount)}</b></p>`).join("")||`<p>${esc(t("Ninguno.","None."))}</p>`}<h2>${esc(t("METAS","GOALS"))}</h2>${d.plans.map(x=>`<p>${esc(x.name||"")} — ${esc(t("Meta","Goal"))}: <b>${money(x.target)}</b> · ${esc(t("Guardado","Saved"))}: <b>${money(x.saved)}</b></p>`).join("")||`<p>${esc(t("Ninguna.","None."))}</p>`}<p>${esc(t("Este documento contiene información organizada por el usuario. REMESAS no es software de impuestos ni preparador de impuestos.","This document contains information organized by the user. REMESAS is not tax software or a tax preparer."))}</p>`;printPDF(t("Mis datos REMESAS","My REMESAS data"),body)}
async function exportLearningPDF(){try{const d=await api("/api/learning-pdf");if(d.url){window.open(d.url,"_blank","noopener,noreferrer");return}if(d.download_url){window.open(d.download_url,"_blank","noopener,noreferrer");return}if(d.html){const w=window.open("","_blank","noopener,noreferrer");if(w){w.document.write(d.html);w.document.close();return}}}catch{}const lessons=window.lessons||[],body=`<h1>REMESAS — ${esc(t("GUÍA PARA APRENDER","LEARNING GUIDE"))}</h1><p>${esc(t("Guía original de REMESAS para entender el proceso de una remesa.","Original REMESAS guide for understanding the remittance process."))}</p>${lessons.map((x,i)=>`<div class="box"><h2>${esc(x.title||`Paso ${i+1}`)}</h2><p>${esc(x.text||x.description||x.summary||"")}</p></div>`).join("")}<p>${esc(t("La información actual sobre tarifas, tasas, disponibilidad y condiciones debe confirmarse directamente con la remesadora oficial.","Current information about fees, rates, availability, and terms must be confirmed directly with the official provider."))}</p>`;printPDF(t("Guía REMESAS","REMESAS Guide"),body)}
function pickPDF(){const input=document.createElement("input");input.type="file";input.accept="application/pdf,.pdf";input.onchange=()=>{if(input.files?.[0])restorePDF(input.files[0])};input.click()}
async function restorePDF(file){if(!/\.pdf$/i.test(file.name)&&file.type!=="application/pdf")return showError(t("Elige un archivo PDF.","Choose a PDF file."));renderShell(`<section class="section"><div class="card"><div class="spinner"></div><h2>${esc(t("LEER MI PDF","READ MY PDF"))}</h2><p>${esc(t("Estamos buscando tus datos guardados para volver a ponerlos en su lugar.","We are looking for your saved information so we can put it back in place."))}</p></div></section>`,t("Recuperar","Recover"));try{let result=null;for(const u of ["/api/pdf/import","/api/pdf/restore","/api/import/pdf"]){try{const fd=new FormData();fd.append("file",file);const h={};const z=token();if(z)h["X-Remesas-Access-Token"]=z;h["X-Remesas-Language"]=APP.lang;const r=await fetch(u,{method:"POST",headers:h,body:fd});if(r.ok){result=await r.json();break}}catch{}}if(result?.data){applyImportedData(result.data);return}const raw=await file.arrayBuffer(),text=new TextDecoder().decode(raw),m=text.match(/REMESAS_DATA:([A-Za-z0-9+/=]+)/g);if(m?.length){const last=m[m.length-1].replace(/^REMESAS_DATA:/,"");try{applyImportedData(JSON.parse(decodeURIComponent(escape(atob(last)))));return}catch{}}renderShell(`<section class="section"><div class="card"><h1>${esc(t("NO PUDE RECUPERAR ESTE PDF","I COULD NOT RECOVER THIS PDF"))}</h1><p>${esc(t("Necesito el PDF que guardaste desde REMESAS. Busca ese archivo e inténtalo otra vez.","I need the PDF you saved from REMESAS. Find that file and try again."))}</p><button class="btn" onclick="pickPDF()">${esc(t("ELEGIR OTRO PDF","CHOOSE ANOTHER PDF"))}</button><button class="btn secondary" onclick="renderHome()">${esc(t("VOLVER","BACK"))}</button></div></section>`,t("Recuperar","Recover"))}catch{showError(t("No pude leer ese PDF. Conserva el archivo e inténtalo de nuevo.","I could not read that PDF. Keep the file and try again."))}}
function applyImportedData(data){if(!data||data.kind!=="REMESAS_MONEY")return showError(t("Este no parece ser un PDF de REMESAS.","This does not appear to be a REMESAS PDF."));if(data.money)setJSON(APP.moneyKey,data.money);if(Array.isArray(data.expenses))setJSON(APP.expensesKey,data.expenses);if(Array.isArray(data.savings))setJSON(APP.savingsKey,data.savings);if(Array.isArray(data.family))setJSON(APP.familyKey,data.family);if(Array.isArray(data.plans))setJSON(APP.plansKey,data.plans);const m=getMoneyState();recalcMoney(m);setJSON(APP.moneyKey,m);renderShell(`<section class="section"><div class="card"><h1>✅ ${esc(t("TUS DATOS HAN VUELTO","YOUR DATA IS BACK"))}</h1><p>${esc(t("Recuperamos tus registros y volvimos a calcular lo que tienes, lo que entra, lo que sale, lo que guardas y lo que queda.","We recovered your records and recalculated what you have, what comes in, what goes out, what you save, and what remains."))}</p><div class="notice"><h2>${money(m.available)}</h2><p>${esc(t("Este es el dinero que queda según la información recuperada y los registros actuales.","This is the money left according to the recovered information and current records."))}</p></div><button class="btn" onclick="renderPuedo()">${esc(t("VER MI DINERO","SEE MY MONEY"))}</button></div></section>`,t("Datos recuperados","Data recovered"))}
function understandNeed(){const el=document.getElementById("freeNeed"),text=(el?.value||"").trim();if(!text)return showError(t("Escribe qué necesitas.","Write what you need."));const amountMatch=text.match(/(\$?\s?\d+(?:[.,]\d{1,2})?)/),countries=APP.config?.countries||[];let dest=null;for(const c of countries){const names=[c.id,c.code,c.name?.es,c.name?.en,...(c.aliases||[])].filter(Boolean).map(String);if(names.some(n=>text.toLowerCase().includes(n.toLowerCase()))){dest=String(c.id||c.code).toUpperCase();break}}if(amountMatch&&dest){beginParsedRemittance({amount:num(amountMatch[1].replace(/,/g,"")),destination_country:dest});return}if(/ahorr|guardar|meta|carro|casa|viaje|compr/i.test(text))return renderGoals();if(/gast|pagar|comida|renta|alquiler/i.test(text))return renderExpenses();renderHelp()}
async function beginParsedRemittance(x){if(!await ensureService())return;await renderRemittance(x)}
function showError(m){const old=document.querySelector(".toast");if(old)old.remove();const b=document.createElement("div");b.className="toast";b.textContent=m;document.body.appendChild(b);setTimeout(()=>b.remove(),6000)}
async function changeLanguage(){APP.lang=APP.lang==="es"?"en":"es";localStorage.setItem("remesas_lang_v4",APP.lang);await loadConfig();renderHome()}
function deleteLocalData(){if(!confirm(t("¿Quieres borrar tus datos guardados en este dispositivo? Se borrarán dinero, gastos, familia, ahorros y metas.","Do you want to delete your saved data on this device? Money, expenses, family, savings, and goals will be deleted.")))return;[APP.moneyKey,APP.expensesKey,APP.familyKey,APP.prefsKey,APP.savingsKey,APP.plansKey,"remesas_purchase_v4"].forEach(k=>localStorage.removeItem(k));location.reload()}
async function start(){try{await loadConfig();if(await verifyAccess()){if(!APP.session)await startService();if(APP.session)renderHome();else renderGate()}else renderGate()}catch{renderGate()}}
Object.assign(window,{renderHome,renderAbout,renderRemittance,renderMoney,renderWeek,renderPeriod,renderExpenses,renderFamily,renderHelp,renderPurchase,renderSavings,renderGoals,renderTengo,renderGano,renderPuedo,renderHago,renderQuickGuide,renderLearn,showLesson,changeLanguage,understandNeed,beginParsedRemittance,compare,showComparison,selectProvider,renderFinalCheck,finishCheck,renderComparisonFromSession:function(){APP.session?compare():renderRemittance()},openOfficial,calculateMoney:renderMoney,addExpense,removeExpense,saveFamily,removeFamily,saveSavings,removeSavings,savePlan,removePlan,checkPurchase,showHelpTopic,deleteLocalData,pickPDF,restorePDF,exportMoneyPDF,exportLearningPDF,startPaidAccess,showServiceInfo,showAdmin,adminLogin,saveTengo,saveGano});
start();
